import com.nusukconnect.companion.Rules;
import java.util.*;

public final class RulesTest {
    private static int checks;
    static void expect(boolean condition,String name) {
        checks++; if (!condition) throw new AssertionError(name);
    }
    public static void main(String[] args) {
        expect("DOOR".equals(Rules.codeResultRecoveryStage("Choose a door",false,0,230,0)),"pending code continues with available keys");
        expect("DOOR".equals(Rules.codeResultRecoveryStage("Choose a door",false,0,null,0)),"missing accessibility key counter cannot stall challenge recovery");
        expect("SOURCE_GENERATE".equals(Rules.codeResultRecoveryStage("Choose a door",false,0,0,0)),"zero keys regenerates code");
        expect("SOURCE_GENERATE".equals(Rules.codeResultRecoveryStage("Choose a door",false,1,230,0)),"code-only mode does not spend a key");
        expect("OPEN_DOOR".equals(Rules.codeResultRecoveryStage("Do you want to use your key?",false,0,null,0)),"open door confirmation resumes without a readable counter");
        expect("QUESTION".equals(Rules.codeResultRecoveryStage("Check your answer",true,0,0,0)),"already opened question continues even after the last key was spent");
        expect(Rules.codeResultRecoveryStage("Check the code",false,0,null,14999)==null,"allow code result to arrive before abandoning it");
        expect("SOURCE_GENERATE".equals(Rules.codeResultRecoveryStage("Check the code",false,0,null,15000)),"lost result on code form starts a different code after grace period");
        expect("SOURCE_GENERATE".equals(Rules.codeResultRecoveryStage("Your keys",false,0,1,15000)),"lost result on key list does not stall");
        expect(Rules.codeResultRecoveryStage("You got a new key",false,0,1,20000)==null,"explicit acceptance uses normal accounting");
        expect(Rules.codeResultRecoveryStage("The entered code is not correct",false,0,1,20000)==null,"explicit rejection uses normal accounting");
        expect(Rules.codeResultRecoveryStage("Start the challenge",false,0,null,20000)==null,"Home still navigates to challenge rather than generating repeatedly");
        expect(!Rules.retryDoorSelection("Choose a door",2999),"give category tap time to navigate");
        expect(Rules.retryDoorSelection("Choose a door",3000),"retry category when successful accessibility tap did not open it");
        expect(!Rules.retryDoorSelection("Choose a door\nDo you want to use your key?",3000),"confirmation takes priority over background category labels");
        expect("DOOR".equals(Rules.codeResultQuizStage("Start the challenge\nChoose a door\nThe Prophet’s Biography\nThe Quran\nMakkah and the Grand Mosque\nMadinah and the Prophet’s Mosque\n230\nPlay\nKeys")),"reported challenge screen exits stale code-result navigation to select a door");
        expect("OPEN_DOOR".equals(Rules.codeResultQuizStage("Do you want to use your key?\nOpen the door")),"already-selected door resumes its confirmation");
        expect(Rules.codeResultQuizStage("Start the challenge\nHome\nStore")==null,"Home alone does not imply a door is available");
        expect(Rules.codeResultQuizStage("Your keys\nCheck the code")==null,"code form remains a code-result screen");
        expect("Start the challenge".equals(Rules.codeResultNavigation(List.of("Motawef","Quran","100 Umrah trips","Start the challenge","Haircut","Electric Carts","Home","Journey","Store","NusukAI"))),"pending code on reported Home screen navigates at challenge button instead of scrolling past it");
        expect("Start the challenge →".equals(Rules.codeResultNavigation(List.of("Start the challenge →","Home"))),"challenge arrow label retained for recovery click");
        expect("Keys".equals(Rules.codeResultNavigation(List.of("Play","Winners","Keys","Share"))),"pending result reopens Keys without resubmitting");
        expect("Add code to get new key".equals(Rules.codeResultNavigation(List.of("Your keys","Add code to get new key"))),"collapsed key form can be reopened for pending result");
        expect(Rules.codeResultNavigation(List.of("Check the code","Home","Store"))==null,"pending result never selects the code submission button");
        expect(Rules.codeResultNavigation(List.of("Add code to get new key","Check the code","Keys"))==null,"open code form waits for result without clicking Keys or reopening the form");
        expect(Rules.validLimit(true,1)&&Rules.validLimit(true,349),"enabled limit accepts supported endpoints");
        expect(!Rules.validLimit(true,0)&&!Rules.validLimit(true,350),"enabled limit rejects out of range values");
        expect(Rules.validLimit(false,0),"disabled limit does not validate a hidden empty value");
        expect(!Rules.limitReached(true,4,5),"enabled limit allows remaining attempts");
        expect(Rules.limitReached(true,5,5),"enabled limit stops exactly at the configured count");
        expect(Rules.limitReached(true,7,5),"lowering enabled limit below today's count stops further attempts");
        expect(!Rules.limitReached(false,349,1),"disabled limit ignores saved count for both code and quiz continuation");
        expect(!Rules.limitReached(false,1000,349),"disabled limit has no hidden 349-attempt cap");
        expect(!Rules.limitReached(false,1,0),"disabled limit does not stop on an unused invalid saved number");
        expect(Rules.challengeLabel("Start the challenge -->"),"challenge button with ASCII arrow recognized");
        expect(Rules.challengeLabel("Start the challenge →"),"challenge button with Unicode arrow recognized");
        expect(Rules.challengeLabel("Start\nthe challenge  →"),"wrapped challenge label recognized");
        expect(!Rules.challengeLabel("Restart the challenge later"),"unrelated text cannot trigger challenge navigation");
        expect(Integer.valueOf(0).equals(Rules.keyCount("0")),"zero in scoped key counter recognized");
        expect(Integer.valueOf(3).equals(Rules.keyCount("3 keys")),"positive key count recognized");
        expect(Integer.valueOf(2).equals(Rules.keyCount("Your keys: 2")),"labeled key count recognized");
        expect(Rules.keyCount("Draw at 17:00")==null,"unrelated numbers are not a key count");
        expect(Rules.noKey("You don't have any key\nClose"),"reported singular no-key popup recognized");
        expect(!Rules.noKey("Which companion did not have a horse?"),"unrelated missing-item wording is not a no-key popup");
        expect("NG-L5uco7od".equals(Rules.code(List.of("Your Fresh Code","NG-L5uco7od","1. NG-abcdefgh"))),"mixed-case current code preserved");
        expect(Rules.code(List.of("1. NG-abcdefgh"))==null,"numbered code history is not current code");
        expect(Rules.code(List.of("1. NG-abcdefgh\n2. NG-12345678"))==null,"multiline history exposed by the installed app is excluded");
        expect(Rules.code(List.of("NG-short","NG-abcdefghX"))==null,"malformed or longer codes are rejected");
        expect(Rules.acceptedCode("Congratulations\nYou got a new key! Go to the doors"),"recorded redemption success");
        expect(!Rules.acceptedCode("Check the code"),"submission button is not success");
        expect(!Rules.acceptedCode("Invalid code"),"invalid redemption not success");
        expect(Rules.rejectedCode("This code has already been used"),"used-code response");
        expect(Rules.rejectedCode("The code already has been used, please enter a new code."),"actual phone rejection triggers fresh generation instead of a result timeout");
        expect(Rules.rejectedCode("Check the code\nThe code already has been used, please enter a new code.\nPlay\nKeys"),"rejection is recognized within the full code entry screen");
        expect(Rules.rejectedCode("This code has already been redeemed"),"redeemed-code wording also triggers fresh generation");
        expect(Rules.rejectedCode("The entered code is not correct, please ensure to enter the correct code."),"actual invalid-code message triggers fresh generation");
        expect(Rules.rejectedCode("Challeng keys\nYour keys\n231\nAdd code to get new key\nThe entered code is not correct, please ensure to enter the correct code.\nCheck the code\nPlay\nKeys"),"reported CODE_RESULT screen recovers instead of waiting for the watchdog");
        expect(Rules.rejectedCode("The entered code is not\ncorrect, please ensure to enter the correct code."),"wrapped rejection text also recovers");
        expect(!Rules.rejectedCode("Enter the correct code\nCheck the code"),"code instructions alone do not discard a fresh code");
        expect(!Rules.rejectedCode("Add code to get new key\nCheck the code"),"normal code form does not trigger rejection recovery");
        expect(Rules.blocked("For security reasons, Nusuk can't run on this device."),"device restriction recognized");
        expect(Rules.correctAnswer(List.of("Correct! You're in the draw")),"quiz success recognized");
        expect(!Rules.correctAnswer(List.of("Incorrect!","Wrong answer")),"incorrect is never counted as correct");
        expect(Rules.wrongAnswer(List.of("Incorrect!","Play again")),"incorrect result advances the user-requested loop");
        expect(Rules.wrongAnswer(List.of("Wrong answer","Play again")),"wrong-answer result advances the loop");
        expect(Rules.wrongAnswer(List.of("Sorry, your answer is incorrect.")),"alternate wrong-result wording recognized");
        expect(!Rules.wrongAnswer(List.of("Correct!","Which statement is incorrect?")),"question wording and correct result are not a wrong-result marker");
        expect(Rules.answer("A new question?",Rules.seeds())==null,"unseen questions are never guessed");
        expect("Ahmad".equals(Rules.answer("By what name did Jesus (peace be upon him) give glad tidings of the Prophet (PBUH)?",Rules.seeds())),"corrected recorded answer");
        expect("The Torah".equals(Rules.answer("Which book did God reveal to Moses (peace be upon him)?",Rules.seeds())),"recorded Torah answer");
        expect(Rules.question(List.of("Do you want to use your key?","Which book?" )).equals("Which book?"),"confirmation is not a quiz question");
        String wrappedQuestion="Which book did God reveal\nto Moses (peace be upon him)?";
        List<String> wrappedLabels=List.of("Play","Keys",wrappedQuestion,"The Torah","The Gospel","The Psalms","The Quran","Check your answer");
        List<String> wrappedChoices=List.of("The Torah","The Gospel","The Psalms","The Quran");
        expect(wrappedQuestion.equals(Rules.question(wrappedLabels)),"multiline question remains intact");
        expect(wrappedChoices.equals(Rules.choices(wrappedLabels,wrappedQuestion)),"multiline question allows four choices to be read");
        expect(Rules.sameQuestion(wrappedQuestion,wrappedChoices,wrappedQuestion,Rules.choices(wrappedLabels,wrappedQuestion)),"unchanged multiline question can pass pre-submission verification");
        expect(Rules.choices(List.of(wrappedQuestion,"The Torah","The Gospel","The Psalms","Check your answer"),wrappedQuestion).isEmpty(),"multiline question with a missing choice still pauses");
        Map<String,String> taught=new HashMap<>(Rules.seeds());taught.put(Rules.normalize("Who is this?"),"Exact option");
        expect("Exact option".equals(Rules.answer("  WHO is this?  ",taught)),"taught question matches whitespace and case");
        expect("Khalid ibn al-Walid".equals(Rules.answer("Which companion was nicknamed “the Drawn Sword of Allah”?",Rules.seeds())),"new observed question has a verified answer");
        expect(Rules.answerOptions("Khalid ibn al-Walid").contains("Khalid bin al-Walid"),"known transliteration supported");
        expect(!Rules.answerOptions("Khalid ibn al-Walid").contains("Khalid ibn Said"),"a different companion cannot match");
        expect(Rules.resumeQuiz(0,true,1,0,1),"final code resumes quiz after restart");
        expect(Rules.resumeQuiz(0,false,1,0,1),"existing installation recovers an accepted code with no quiz");
        expect(!Rules.resumeQuiz(1,true,1,0,1),"code-only mode does not spend a quiz key");
        expect(!Rules.resumeQuiz(0,true,1,1,1),"quiz limit respected after submission");
        expect(Rules.resumeQuiz(2,false,0,0,1),"quiz-only mode can use an existing key");
        expect(!Rules.resumeQuiz(0,false,0,0,1),"no quiz is due before code redemption");
        expect(Rules.doorLabel("The Prophet’s Biography",0),"full category name and curly apostrophe match");
        expect(Rules.doorLabel("Makkah and the\nHoly Sites",2),"multiline category name matches");
        expect(!Rules.doorLabel("The Quran",0),"another door cannot match");
        expect(!Rules.doorLabel("Choose a door\nThe Prophet's Biography",0),"combined page text is not a door label");
        expect(Rules.quizNavigationScreen("Start the challenge"),"stale question can recover from the challenge home");
        expect(Rules.quizNavigationScreen("Choose a door"),"stale question can recover from the door page");
        expect(Rules.quizNavigationScreen("Your keys"),"stale question can recover from keys");
        expect(!Rules.quizNavigationScreen("Sign in to your account"),"authentication is not treated as quiz navigation");
        String restoredResult="Correct! You're in the draw for an Umrah trip for two and 20 cartons of Zamzam water.\nDraw time\nThis evening, Saudi time\nPlay again\nShare & get a chance to win!\n0\n0";
        expect(Rules.quizNavigationScreen(restoredResult),"actual result restored during SET_CODE recovers through Play again");
        expect(!Rules.codeEntryReady(false,restoredResult),"restored quiz result cannot receive a code");
        expect(!Rules.codeEntryReady(true,"Check the code\n"+restoredResult),"transient old code field on a restored result cannot receive a code");
        expect(Rules.codeEntryReady(true,"Keys\nEnter your code\nCheck the code"),"visible code form is ready for entry");
        expect(!Rules.codeEntryReady(false,"Check the code"),"code form requires an editable field");
        expect(Rules.codeEntryReady(true,"Your keys\nEnter your code"),"visible input is usable before scrolling down to submit button");
        expect(Rules.codeFormScreen("Keys\nEnter the code"),"code form remains recognized when submit button is below viewport");
        expect(!Rules.codeEntryReady(true,"Enter your code\nCorrect!\nPlay again"),"old input on a restored result is still rejected");
        expect(Rules.keyListScreen("Challeng keys\nYour keys\n0\nOops! You don’t have any keys\nShare the app and collect keys\n0\n0"),"actual stalled second-cycle screen is recognized for scrolling to Add code");
        expect(!Rules.keyListScreen("Choose a door\nThe Quran"),"door page is not scrolled as a key list");
        expect(!Rules.keyListScreen("Correct! You're in the draw\nPlay again"),"quiz result is not scrolled as a key list");
        expect(Rules.noKey("You don't have any keys"),"no-key confirmation triggers code generation in combined mode");
        expect(!Rules.noKey("Do you want to use your key?"),"normal door confirmation is not a missing key");
        expect(!Rules.resumeQuestion(1,true),"redemption-only ignores an old unanswered quiz");
        expect(Rules.resumeQuestion(0,true),"full workflow resumes its unanswered quiz");
        expect(Rules.resumeQuestion(2,true),"quiz-only resumes its unanswered quiz");
        expect(!Rules.resumeQuestion(0,false),"full workflow does not invent an open question");
        expect(Rules.initialStage(0,false,false,false,false).equals("SOURCE_GENERATE"),"full workflow starts in the code generator");
        expect(Rules.initialStage(0,false,false,true,true).equals("RECOVER_QUIZ"),"full workflow resumes its waiting question instead of spending another key");
        expect(Rules.initialStage(0,false,false,false,true).equals("NAV_KEYS"),"full workflow resumes an unsubmitted copied code");
        expect(Rules.initialStage(0,true,false,true,true).equals("CODE_RESULT"),"uncertain code submission is checked before a new full cycle");
        expect(Rules.initialStage(0,false,true,true,true).equals("QUIZ_RESULT"),"uncertain quiz submission is checked before a new full cycle");
        expect(Rules.initialStage(1,false,false,true,false).equals("SOURCE_GENERATE"),"redemption task starts code generation despite an old question");
        expect(Rules.initialStage(1,false,false,true,true).equals("NAV_KEYS"),"redemption-only can continue its unsubmitted generated code");
        expect(Rules.initialStage(2,false,false,true,true).equals("RECOVER_QUIZ"),"quiz-only resumes its question without generating a code");
        expect(Rules.initialStage(2,false,false,false,true).equals("NAV_QUIZ"),"quiz-only opens doors with existing keys");
        expect(Rules.doorOrder("2,0,3,1",new Random(7)).equals(List.of(2,0,3,1)),"saved random door order survives resume");
        expect(new HashSet<>(Rules.doorOrder("",new Random(7))).equals(Set.of(0,1,2,3)),"random rotation visits all four doors once");
        expect(new HashSet<>(Rules.doorOrder("0,0,2,3",new Random(7))).equals(Set.of(0,1,2,3)),"duplicate saved doors regenerate a full rotation");
        expect(new HashSet<>(Rules.doorOrder("4,1,2,3",new Random(7))).equals(Set.of(0,1,2,3)),"random selector itself is never treated as a quiz door");
        System.out.println("Passed "+checks+" matching and result checks.");
    }
}
